import fs from "node:fs";
import path from "node:path";
import { ensureDir, readJson } from "./fs-utils.ts";
import { parseFrontmatter } from "./frontmatter.ts";

type Json = Record<string, unknown>;

export interface GenerateAgentsOptions {
  eccRoot: string;
  configRoot: string;
  outRoot: string;
  /** Ref from ecc.lock, stamped into the generated file for reproducibility. */
  sourceRef?: string | null;
}

export interface GenerateAgentsResult {
  agents: string[];
  version: string;
  warnings: string[];
}

const CLAUDE_TO_PI_TOOLS: Record<string, string[]> = {
  read: ["read"],
  grep: ["grep"],
  glob: ["find", "ls"],
  bash: ["bash"],
  write: ["write"],
  edit: ["edit"],
  ls: ["ls"],
  find: ["find"],
};

function mapTools(toolsField: string | undefined): { eccTools: string[]; piTools: string[]; unmapped: string[] } {
  const eccTools = String(toolsField || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const out = new Set<string>();
  const unmapped: string[] = [];
  for (const tool of eccTools) {
    const key = tool.toLowerCase();
    const mapped = CLAUDE_TO_PI_TOOLS[key];
    if (mapped) {
      for (const piTool of mapped) out.add(piTool);
    } else if (/^mcp__/.test(tool)) {
      unmapped.push(tool);
    } else {
      out.add(key);
      unmapped.push(tool);
    }
  }
  return { eccTools, piTools: [...out], unmapped };
}

function readEccVersion(eccRoot: string): string {
  const versionFile = path.join(eccRoot, "VERSION");
  if (fs.existsSync(versionFile)) return fs.readFileSync(versionFile, "utf8").trim();
  const pkgFile = path.join(eccRoot, "package.json");
  if (fs.existsSync(pkgFile)) return String(readJson<Json>(pkgFile).version ?? "unknown");
  return "unknown";
}

export function generateAgents(options: GenerateAgentsOptions): GenerateAgentsResult {
  const eccRoot = path.resolve(options.eccRoot);
  const subsetPath = path.join(path.resolve(options.configRoot), "agents-subset.json");
  const outPath = path.join(path.resolve(options.outRoot), "config", "agents-generated.json");
  if (!fs.existsSync(eccRoot)) throw new Error(`ECC root not found: ${eccRoot}`);

  const subset = readJson<{ agents: string[] }>(subsetPath);
  const version = readEccVersion(eccRoot);
  const warnings: string[] = [];
  const agents: Json[] = [];

  for (const name of subset.agents) {
    const srcPath = path.join(eccRoot, "agents", `${name}.md`);
    if (!fs.existsSync(srcPath)) throw new Error(`Missing ECC agent: ${srcPath}`);
    const raw = fs.readFileSync(srcPath, "utf8");
    const { data, body } = parseFrontmatter(raw);
    const { eccTools, piTools, unmapped } = mapTools(data.tools);
    if (unmapped.length > 0) {
      warnings.push(`Agent ${name}: tools without Pi mapping [${unmapped.join(", ")}] were not passed to --tools.`);
    }
    agents.push({
      name: data.name || name,
      source: `ecc/agents/${name}.md`,
      description: data.description || "",
      model: data.model || "",
      eccTools,
      piTools,
      unmappedTools: unmapped,
      systemPrompt: body,
    });
  }

  const output = {
    sourceVersion: version,
    sourceRef: options.sourceRef ?? null,
    source: "Generated by scripts/build-agents.ts from ecc/agents/*.md (subset in config/agents-subset.json).",
    subset: subset.agents,
    toolMapping: {
      Read: "read",
      Grep: "grep",
      Glob: "find,ls",
      Bash: "bash",
      Write: "write",
      Edit: "edit",
      note: "Unknown/MCP tools are reported in unmappedTools; Pi --tools allowlist receives only mapped Pi tool names.",
    },
    agents,
  };

  ensureDir(path.dirname(outPath));
  fs.writeFileSync(outPath, `${JSON.stringify(output, null, 2)}\n`, "utf8");
  return { agents: subset.agents, version, warnings };
}
